<?php
declare(strict_types=1);require_once __DIR__.'/config/lead_step20.php';$error=null;$dataset=(string)($_GET['dataset']??'leads');$format=(string)($_GET['format']??'view');$rows=[];$headers=[];try{$pdo=business_db();$ctx=lead_step20_context($pdo);$orgId=(int)$ctx['organization_id'];if($dataset==='appointments'){$headers=['Code','Lead','Name','Start','Mode','Status','Purpose'];$s=$pdo->prepare("SELECT a.appointment_code,l.lead_code,l.full_name,a.start_at,a.appointment_mode,a.status,a.purpose FROM crm_appointments a JOIN crm_leads l ON l.id=a.lead_id WHERE a.organization_id=? ORDER BY a.start_at DESC");$s->execute([$orgId]);$rows=$s->fetchAll(PDO::FETCH_NUM);}elseif($dataset==='followups'){$headers=['Lead','Name','Type','Subject','Due','Status','Completed'];$s=$pdo->prepare("SELECT l.lead_code,l.full_name,t.task_type,t.subject,t.due_at,t.status,t.completed_at FROM crm_lead_tasks t JOIN crm_leads l ON l.id=t.lead_id WHERE t.organization_id=? ORDER BY t.due_at DESC");$s->execute([$orgId]);$rows=$s->fetchAll(PDO::FETCH_NUM);}else{$dataset='leads';$headers=['Lead Code','Type','Name','Mobile','Email','Stage','Priority','Submissions','First Seen','Last Seen','Customer ID','Member ID'];$s=$pdo->prepare("SELECT lead_code,lead_type,full_name,mobile,email,stage,priority,submission_count,first_seen_at,last_seen_at,converted_customer_id,converted_member_id FROM crm_leads WHERE organization_id=? ORDER BY id DESC");$s->execute([$orgId]);$rows=$s->fetchAll(PDO::FETCH_NUM);}if($format==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="step20_'.$dataset.'_'.date('Ymd-His').'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');fputcsv($out,$headers);foreach($rows as $r)fputcsv($out,$r);fclose($out);exit;}}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Lead Export</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"><style>@media print{.no-print{display:none!important}body{background:#fff}.os-card{box-shadow:none}}</style></head><body><header class="os-topbar no-print"><div class="os-topbar-inner"><a class="os-brand" href="lead_center.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>STEP 20 • Lead Export</small></span></a><div class="os-top-actions"><a class="os-btn primary" href="lead_center.php">Leads</a></div></div></header><main class="os-main" style="max-width:1500px;margin:auto"><section class="os-card no-print"><h2>Export Center</h2><div class="os-links"><?php foreach(['leads'=>'Leads','appointments'=>'Appointments','followups'=>'Follow-ups'] as $k=>$label):?><a class="os-btn" href="?dataset=<?= $k ?>"><?= $label ?></a><a class="os-btn" href="?dataset=<?= $k ?>&format=csv">CSV</a><?php endforeach;?><button class="os-btn" onclick="window.print()">Print / Save PDF</button></div></section><?php if($error):?><div class="pp-alert bad"><?= lead_step20_h($error) ?></div><?php endif;?><section class="os-card" style="margin-top:14px"><h2><?= lead_step20_h(ucwords($dataset)) ?></h2><div style="overflow:auto"><table style="width:100%;border-collapse:collapse"><thead><tr><?php foreach($headers as $h):?><th style="text-align:left;padding:8px;border-bottom:1px solid #ddd"><?= lead_step20_h($h) ?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($r as $v):?><td style="padding:8px;border-bottom:1px solid #eee"><?= lead_step20_h($v) ?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></section></main><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
